using EmployeeAttendanceSystem.Models;
using Microsoft.EntityFrameworkCore;
namespace EmployeeAttendanceSystem.Data;
public class AppDbContext : DbContext { public AppDbContext(DbContextOptions<AppDbContext> o):base(o){} public DbSet<User> Users=>Set<User>(); public DbSet<Attendance> Attendances=>Set<Attendance>(); public DbSet<LeaveRequest> LeaveRequests=>Set<LeaveRequest>(); protected override void OnModelCreating(ModelBuilder b){ b.Entity<User>().HasIndex(x=>x.Email).IsUnique(); b.Entity<Attendance>().HasIndex(x=>new{x.UserId,x.Date}).IsUnique(); b.Entity<Attendance>().HasOne(x=>x.User).WithMany().HasForeignKey(x=>x.UserId).OnDelete(DeleteBehavior.Cascade); b.Entity<LeaveRequest>().HasOne(x=>x.User).WithMany().HasForeignKey(x=>x.UserId).OnDelete(DeleteBehavior.Cascade); } }
public static class DbSeeder { public static void Seed(AppDbContext db){ if(!db.Users.Any()){ db.Users.Add(new User{Name="HR Admin",Email="hr@demo.com",PasswordHash=Hash("Admin@123"),Role="HR",IsActive=true,CreatedAt=DateTime.UtcNow}); db.Users.Add(new User{Name="Demo Employee",Email="employee@demo.com",PasswordHash=Hash("Employee@123"),Role="Employee",IsActive=true,CreatedAt=DateTime.UtcNow}); db.SaveChanges(); } } private static string Hash(string s)=>Convert.ToBase64String(System.Security.Cryptography.Rfc2898DeriveBytes.Pbkdf2(s,System.Text.Encoding.UTF8.GetBytes("EmployeeAttendanceSalt2026"),100000,System.Security.Cryptography.HashAlgorithmName.SHA256,32)); }
